from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
import csv
import math
import re

from .code_aster_study import LinearStaticStudy


class CodeAsterResultContractError(RuntimeError):
    pass


_LOCAL_ASCII_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$")


@dataclass(frozen=True)
class ResultTableSpec:
    displacement_filename: str = "reference_displacement.table"
    reaction_filename: str = "reference_reaction.table"
    stress_filename: str = "reference_stress.table"
    displacement_unit: int = 91
    reaction_unit: int = 92
    stress_unit: int = 93

    def validate(self) -> None:
        names = (self.displacement_filename, self.reaction_filename, self.stress_filename)
        if len({name.lower() for name in names}) != 3:
            raise CodeAsterResultContractError("RESULT_TABLE_FILENAMES_MUST_DIFFER")
        for name in names:
            if Path(name).name != name or not _LOCAL_ASCII_RE.fullmatch(name):
                raise CodeAsterResultContractError("RESULT_TABLE_FILENAME_INVALID")
        units = (self.displacement_unit, self.reaction_unit, self.stress_unit)
        if len(set(units)) != 3 or any(unit in {6, 8, 9, 20, 80} or not 10 <= unit <= 99 for unit in units):
            raise CodeAsterResultContractError("RESULT_TABLE_LOGICAL_UNITS_INVALID")


@dataclass(frozen=True)
class ParsedReferenceMetrics:
    load_face_mean_ux_mm: float
    support_reaction_x_n: float
    axial_stress_mpa: float


def render_reference_linear_static_comm(
    study: LinearStaticStudy,
    *,
    volume_group: str = "SOLID",
    tables: ResultTableSpec | None = None,
) -> str:
    """Render a reference-study command file with auditable result extraction.

    Contract basis:
    - DEFI_GROUP creates node groups associated with the MED element groups.
    - CALC_CHAMP explicitly computes SIGM_NOEU and REAC_NODA.
    - POST_RELEVE_T extracts a mean load-face UX, the support reaction resultant,
      and a benchmark-only mean SIXX on the solid node group.
    - IMPR_TABLE writes deterministic ASCII evidence files through DEFI_FICHIER.

    The mean nodal SIXX is a verification metric for the uniform axial reference
    case only; it is not a general-purpose stress-recovery definition.
    """
    study.validate()
    spec = tables or ResultTableSpec()
    spec.validate()
    if not re.fullmatch(r"[A-Za-z][A-Za-z0-9_]{0,23}", volume_group):
        raise CodeAsterResultContractError("RESULT_VOLUME_GROUP_INVALID")

    fx, fy, fz = study.traction_mpa
    return f"""# Generated by AsterMax C8.4 reference-result contract.\n# Units: mm / N / MPa. Table outputs are verification evidence, not display-only data.\nDEBUT()\n\nmesh = LIRE_MAILLAGE(FORMAT='MED', UNITE=20)\n\n# Build node groups from verified MED element groups so POST_RELEVE_T has explicit supports.\nmesh = DEFI_GROUP(\n    reuse=mesh,\n    MAILLAGE=mesh,\n    CREA_GROUP_NO=(\n        _F(GROUP_MA='{study.support_group}'),\n        _F(GROUP_MA='{study.load_group}'),\n        _F(GROUP_MA='{volume_group}'),\n    ),\n)\n\nmodel = AFFE_MODELE(\n    MAILLAGE=mesh,\n    AFFE=_F(TOUT='OUI', PHENOMENE='MECANIQUE', MODELISATION='3D'),\n)\n\nmaterial = DEFI_MATERIAU(ELAS=_F(E={study.young_mpa:.17g}, NU={study.poisson:.17g}))\nmatfield = AFFE_MATERIAU(MAILLAGE=mesh, AFFE=_F(TOUT='OUI', MATER=material))\n\nfixed = AFFE_CHAR_MECA(\n    MODELE=model,\n    DDL_IMPO=_F(GROUP_MA='{study.support_group}', DX=0.0, DY=0.0, DZ=0.0),\n)\n\nload = AFFE_CHAR_MECA(\n    MODELE=model,\n    FORCE_FACE=_F(GROUP_MA='{study.load_group}', FX={fx:.17g}, FY={fy:.17g}, FZ={fz:.17g}),\n)\n\nresult = MECA_STATIQUE(\n    MODELE=model,\n    CHAM_MATER=matfield,\n    EXCIT=(_F(CHARGE=fixed), _F(CHARGE=load)),\n)\n\n# Explicitly request the fields used by the verification harness.\n# REAC_NODA is calculated over the full model so distributed load contributions\n# are not accidentally omitted from the support-equilibrium calculation.\nresult = CALC_CHAMP(\n    reuse=result,\n    RESULTAT=result,\n    CONTRAINTE=('SIGM_ELNO', 'SIGM_NOEU'),\n    CRITERES=('SIEQ_ELNO', 'SIEQ_NOEU'),\n    FORCE=('REAC_NODA',),\n)\n\ndispl = POST_RELEVE_T(\n    ACTION=_F(\n        INTITULE='LOAD_FACE_MEAN_UX',\n        RESULTAT=result,\n        NOM_CHAM='DEPL',\n        NOM_CMP='DX',\n        GROUP_NO='{study.load_group}',\n        OPERATION='MOYENNE_ARITH',\n    ),\n)\n\nreaction = POST_RELEVE_T(\n    ACTION=_F(\n        INTITULE='SUPPORT_REACTION',\n        RESULTAT=result,\n        NOM_CHAM='REAC_NODA',\n        GROUP_NO='{study.support_group}',\n        RESULTANTE=('DX','DY','DZ'),\n        OPERATION='EXTRACTION',\n    ),\n)\n\nstress = POST_RELEVE_T(\n    ACTION=_F(\n        INTITULE='REFERENCE_MEAN_SIXX',\n        RESULTAT=result,\n        NOM_CHAM='SIGM_NOEU',\n        NOM_CMP='SIXX',\n        GROUP_NO='{volume_group}',\n        OPERATION='MOYENNE_ARITH',\n    ),\n)\n\nDEFI_FICHIER(ACTION='ASSOCIER', UNITE={spec.displacement_unit}, FICHIER='{spec.displacement_filename}')\nDEFI_FICHIER(ACTION='ASSOCIER', UNITE={spec.reaction_unit}, FICHIER='{spec.reaction_filename}')\nDEFI_FICHIER(ACTION='ASSOCIER', UNITE={spec.stress_unit}, FICHIER='{spec.stress_filename}')\n\nIMPR_TABLE(TABLE=displ, FORMAT='TABLEAU', SEPARATEUR=';', FORMAT_R='1PE20.12', UNITE={spec.displacement_unit})\nIMPR_TABLE(TABLE=reaction, FORMAT='TABLEAU', SEPARATEUR=';', FORMAT_R='1PE20.12', UNITE={spec.reaction_unit})\nIMPR_TABLE(TABLE=stress, FORMAT='TABLEAU', SEPARATEUR=';', FORMAT_R='1PE20.12', UNITE={spec.stress_unit})\n\nDEFI_FICHIER(ACTION='LIBERER', UNITE={spec.displacement_unit})\nDEFI_FICHIER(ACTION='LIBERER', UNITE={spec.reaction_unit})\nDEFI_FICHIER(ACTION='LIBERER', UNITE={spec.stress_unit})\n\nIMPR_RESU(\n    FORMAT='MED',\n    UNITE=80,\n    RESU=_F(RESULTAT=result, NOM_CHAM=('DEPL','SIGM_ELNO','SIGM_NOEU','SIEQ_ELNO','SIEQ_NOEU','REAC_NODA')),\n)\n\nFIN()\n"""


def _finite(value: str, code: str) -> float:
    try:
        parsed = float(value.replace("D", "E").replace("d", "e"))
    except ValueError as exc:
        raise CodeAsterResultContractError(code) from exc
    if not math.isfinite(parsed):
        raise CodeAsterResultContractError(code)
    return parsed


def _read_table_row(path: str | Path) -> dict[str, str]:
    file = Path(path)
    if not file.is_file() or file.stat().st_size <= 0:
        raise CodeAsterResultContractError("RESULT_TABLE_MISSING")
    lines = [line.strip() for line in file.read_text(encoding="utf-8", errors="strict").splitlines() if line.strip() and not line.lstrip().startswith("#")]
    candidates = [line for line in lines if ";" in line]
    if len(candidates) < 2:
        raise CodeAsterResultContractError("RESULT_TABLE_FORMAT_UNRECOGNIZED")
    reader = csv.DictReader(candidates, delimiter=";")
    rows = list(reader)
    if len(rows) != 1:
        raise CodeAsterResultContractError("RESULT_TABLE_ROW_NOT_UNIQUE")
    return {str(k).strip(): str(v).strip() for k, v in rows[0].items() if k is not None and v is not None}


def parse_reference_result_tables(
    displacement_table: str | Path,
    reaction_table: str | Path,
    stress_table: str | Path,
) -> ParsedReferenceMetrics:
    """Parse the three scalar verification tables; fail closed on ambiguity."""
    disp = _read_table_row(displacement_table)
    reaction = _read_table_row(reaction_table)
    stress = _read_table_row(stress_table)

    def require(row: dict[str, str], *names: str) -> str:
        for name in names:
            if name in row:
                return row[name]
        raise CodeAsterResultContractError("RESULT_TABLE_REQUIRED_COLUMN_MISSING:" + "/".join(names))

    return ParsedReferenceMetrics(
        load_face_mean_ux_mm=_finite(require(disp, "MOYENNE", "DX"), "RESULT_DISPLACEMENT_INVALID"),
        support_reaction_x_n=_finite(require(reaction, "RESULT_X", "DX"), "RESULT_REACTION_INVALID"),
        axial_stress_mpa=_finite(require(stress, "MOYENNE", "SIXX"), "RESULT_STRESS_INVALID"),
    )
